import React, { useEffect, useState } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [live, setLive] = useState({
  jumlah_orang: 0,
  status_listrik: "OFF",
  kondisi: "AMAN"
});
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);

  // ================= LOAD DB =================
  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 5000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");
      setData(res.data);
    } catch (err) {
      console.log(err);
    } finally {
      setLoading(false);
    }
  };

  // ================= REALTIME =================
  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const res = await axios.get("http://127.0.0.1:8000/realtime");
        setLive(res.data);
      } catch (err) {
        console.log("Realtime error", err);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const latest = data.length > 0 ? data[0] : null;

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "#ef4444";
    if (kondisi === "PERINGATAN") return "#f59e0b";
    return "#22c55e";
  };

  const chartData = {
    labels: data.map(d => d.waktu).slice(-10),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).slice(-10),
        borderColor: "#22c55e",
        tension: 0.4
      }
    ]
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "#0f172a", color: "white" }}>

      {/* SIDEBAR */}
      <div style={{ width: 220, background: "#1e293b", padding: 20 }}>
        <h2>⚡ Hematrik</h2>
        <p style={menu} onClick={() => setPage("dashboard")}>Dashboard</p>
        <p style={menu} onClick={() => setPage("monitoring")}>Monitoring</p>
        <p style={menu} onClick={() => setPage("history")}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 30 }}>

        {/* DASHBOARD */}
        {page === "dashboard" && latest && (
          <>
            <h1>📊 Dashboard</h1>

            <div style={card}>{latest.notifikasi}</div>

            <div style={{ display: "flex", gap: 20 }}>
              <div style={card}><h3>People</h3><h1>{latest.jumlah_orang}</h1></div>
              <div style={card}><h3>Listrik</h3><h1>{latest.status_listrik}</h1></div>
              <div style={card}>
                <h3>Kondisi</h3>
                <h1 style={{ color: getColor(latest.kondisi) }}>{latest.kondisi}</h1>
              </div>
            </div>

            <Line data={chartData} />
          </>
        )}

        {/* MONITORING REALTIME */}
{page === "monitoring" && (
  <>
    <h1>📷 CCTV AI</h1>

    {!live && <p>Loading realtime...</p>}

    {live && (
      <div style={{ display: "flex", gap: 30 }}>

        <img
          src="http://127.0.0.1:8000/stream"
          width="700"
          alt=""
          style={{ borderRadius: 10 }}
        />

        <div>
          <div style={card}>
            <h3>👥 People</h3>
            <h1>{live.jumlah_orang}</h1>
          </div>

          <div style={card}>
            <h3>💡 Listrik</h3>
            <h1>{live.status_listrik}</h1>
          </div>

          <div style={card}>
            <h3>⚠️ Kondisi</h3>
            <h2>{live.kondisi}</h2>
          </div>
        </div>

      </div>
    )}
  </>
)}

        {/* HISTORY */}
        {page === "history" && (
          <>
            <h1>History</h1>
            <table style={{ width: "100%" }}>
              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td>{d.kondisi}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

const card = {
  background: "#1e293b",
  padding: 15,
  marginBottom: 10,
  borderRadius: 10
};

const menu = {
  cursor: "pointer",
  marginTop: 10
};

export default App;
